-- Generated by scripts/build_compiled.py from src/fraudrules/rules/structuring/st-001-cash-aggregate-over-ctr.yaml. Do not edit.
-- ST-001 Cash deposits each at or under $10,000 that together exceed it in a day
SELECT 'ST-001' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b ON b.customer_id = a.customer_id AND b.ts <= a.ts AND b.ts > a.ts - 86400
WHERE (a.channel IN ('cash', 'atm') AND a.direction = 'in' AND a.txn_type = 'deposit' AND a.amount_cents <= 1000000) AND (b.channel IN ('cash', 'atm') AND b.direction = 'in' AND b.txn_type = 'deposit' AND b.amount_cents <= 1000000)
GROUP BY a.id
HAVING (COUNT(*) >= 2 AND SUM(b.amount_cents) > 1000000);
